mapper.select:
SELECT

FROM `record`
WHERE id = #{id}
  AND user_id = #{userId}
  AND NOT EXISTS (
    SELECT 1 FROM data_operation_record i JOIN data_operation o ON o.id = i.operation_id
    WHERE i.record_id = `record`.id AND i.user_id = #{userId}
      AND i.item_status IN ('PENDING','RUNNING','RETRY_REQUIRED')
      AND o.status IN ('PENDING','RUNNING','RETRY_REQUIRED')
  )
LIMIT 1

mapper.delete:
DELETE FROM `record`
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'

mapper.update:
UPDATE `record`
SET
    status = 'SAVED',
    draft_expires_at = NULL,
    updated_at = #{now}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'DRAFT'
  AND draft_expires_at > #{now}

UPDATE `record`
SET
    status = 'SEALED',
    sealed_at = #{sealedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'SAVED'

