mapper.update:
UPDATE `record`
SET
    reality_later = #{realityLater},
    reality_later_submit_count = COALESCE(reality_later_submit_count, 0) + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'UNLOCKED'
  AND COALESCE(reality_later_submit_count, 0) < 2

UPDATE `record`
SET
    agent_memory_excluded = #{excluded},
    agent_memory_context_note = #{contextNote},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE `record`
SET
    cover_attachment_id = #{coverAttachmentId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'SAVED')
  AND (status = 'SAVED' OR draft_expires_at IS NULL OR draft_expires_at > #{updatedAt})

UPDATE `record`
SET
    content = #{content},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'SAVED')
  AND (status = 'SAVED' OR draft_expires_at IS NULL OR draft_expires_at > #{updatedAt})

UPDATE `record`
SET
    unlock_at = #{unlockAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'SAVED')
  AND (status = 'SAVED' OR draft_expires_at IS NULL OR draft_expires_at > #{updatedAt})

UPDATE `record`
SET
    cover_attachment_id = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND cover_attachment_id = #{coverAttachmentId}
  AND status IN ('DRAFT', 'SAVED')
  AND (status = 'SAVED' OR draft_expires_at IS NULL OR draft_expires_at > #{updatedAt})

UPDATE `record`
SET updated_at = #{now},
    draft_expires_at = CASE
        WHEN status = 'DRAFT' THEN #{draftExpiresAt}
        ELSE NULL
    END
WHERE id = #{id}
  AND user_id = #{userId}
  AND status IN ('DRAFT', 'SAVED')
  AND (status = 'SAVED' OR draft_expires_at IS NULL OR draft_expires_at > #{now})

mapper.select:
SELECT COUNT(1)
FROM `record` r
WHERE r.user_id = #{userId}
AND NOT EXISTS (
  SELECT 1 FROM data_operation_record i JOIN data_operation o ON o.id = i.operation_id
  WHERE i.record_id = r.id AND i.user_id = #{userId}
    AND i.item_status IN ('PENDING','RUNNING','RETRY_REQUIRED')
    AND o.status IN ('PENDING','RUNNING','RETRY_REQUIRED')
)

    AND r.status = #{status}


    AND r.status <> 'DRAFT'

AND (r.status <> 'DRAFT' OR r.draft_expires_at > CURRENT_TIMESTAMP)

    AND r.record_type = #{recordType}


    AND EXISTS (
        SELECT 1
        FROM record_tag rt
        WHERE rt.record_id = r.id
          AND rt.tag_id = #{tagId}
    )


    AND (
        r.title LIKE CONCAT('%', #{keyword}, '%')
        OR r.content LIKE CONCAT('%', #{keyword}, '%')
    )

