FROM `record` r
ORDER BY r.created_at DESC, r.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT
FROM `record` r WHERE r.user_id = #{userId} AND r.status <> 'SEALED' AND r.agent_memory_excluded = 0 AND NOT EXISTS ( SELECT 1 FROM data_operation_record i JOIN data_operation o ON o.id = i.operation_id WHERE i.record_id = r.id AND i.user_id = #{userId} AND i.item_status IN ('PENDING','RUNNING','RETRY_REQUIRED') AND o.status IN ('PENDING','RUNNING','RETRY_REQUIRED') )
AND r.id <> #{excludeRecordId}
AND r.created_at >= #{createdFrom}
AND (
1 = 0
EXISTS ( SELECT 1 FROM record_tag rt INNER JOIN tag t ON t.id = rt.tag_id AND t.status = 'ENABLED' WHERE rt.record_id = r.id AND rt.tag_id IN
#{tagId}
)
r.title LIKE CONCAT('%', #{keyword}, '%') OR r.core_question LIKE CONCAT('%', #{keyword}, '%') OR r.ai_summary LIKE CONCAT('%', #{keyword}, '%') OR r.belief_then LIKE CONCAT('%', #{keyword}, '%')
) ORDER BY r.created_at DESC, r.id DESC LIMIT #{limit}
